// split.js: find the generated sections inside Candela's assembled program (compiled.shared).
// Pure JavaScript (no Node or browser API), so it runs in the PicoCalc's QuickJS world as well as on the host.
//
// compile.js assembles every program as
//   head + PRELUDE + SPECTRAL + ggxTableWGSL() + sdfCode + hfCode + densCode + CORE + metalAt + matCode + PATH
// PRELUDE, SPECTRAL, CORE and PATH are exported by src/kernel.js. metalAt, hitAlbedo, hitEmission and the default
// customKernel are constant text generated by compile.js; the copies below are those of the pinned version
// (candela-workspace(1).zip, src/compile.js 6f5926cc...). The boundary checks follow ../lib/candela.mjs
// splitProgram(), so the kernel generator and the translator agree on what the fixed kernel is.
//
// The GGX table's numbers are not compared: on the device the table is memoised (PICOCALC-CANDELA-P4 design,
// Section 5), and recomputing it to compare would cost minutes. Its first line must be the `var<private> ETAB`
// declaration, and the constant function ggxE (kernel.js ggxTableWGSL, copied below) must follow it exactly.
export const GGX_E = 'fn ggxE(mu: f32, a: f32) -> f32 {\n  let x: f32 = clamp(mu * 15.0, 0.0, 15.0);\n  let y: f32 = clamp(sqrt(clamp(a, 0.0, 1.0)) * 15.0, 0.0, 15.0);\n  let x0: i32 = i32(floor(x)); let y0: i32 = i32(floor(y));\n  let x1: i32 = min(x0 + 1, 15); let y1: i32 = min(y0 + 1, 15);\n  let fx: f32 = x - f32(x0); let fy: f32 = y - f32(y0);\n  let a0: f32 = mix(ETAB[y0 * 16 + x0], ETAB[y0 * 16 + x1], fx);\n  let a1: f32 = mix(ETAB[y1 * 16 + x0], ETAB[y1 * 16 + x1], fx);\n  return mix(a0, a1, fy);\n}\n';

export const METAL_AT = 'fn metalAt(v: vec3f) -> vec3f {\n  if (SPECTRAL_ON) {\n    let t: f32 = clamp((gLam - 450.0) / 200.0, 0.0, 1.0);\n    let s: f32 = select(mix(v.z, v.y, t * 2.0), mix(v.y, v.x, t * 2.0 - 1.0), t > 0.5);\n    return vec3f(s, s, s);\n  }\n  return v;\n}\n';
export const HIT_ALBEDO = 'fn hitAlbedo(h: Hit, wo: vec3f) -> vec3f { let L: Lobe = evalMaterial(h, wo, 0.5); if (L.kind == 2 && (L.flags & 1) != 0) { return L.c1; } if (L.kind == 1 || L.kind == 4) { return L.c0; } return vec3f(0.8, 0.8, 0.8); }\n';
export const HIT_EMISSION = 'fn hitEmission(h: Hit, wo: vec3f) -> vec3f { let L: Lobe = evalMaterial(h, wo, 0.5); return L.Le; }\n';
export const DEFAULT_CUSTOM = 'fn customKernel(ro: vec3f, rd: vec3f) -> vec3f { return vec3f(1.0, 0.0, 1.0); }\n';

// K: the kernel module's exports { PRELUDE, SPECTRAL, CORE, PATH }.
// Returns { spectral, fieldCode, matCode } or throws an Error naming the boundary that moved.
export function splitProgram(shared, K) {
  const fail = (what) => { throw new Error('splitProgram: ' + what + ' (has Candela changed how compile.js assembles the program?)'); };
  const iP = shared.indexOf(K.PRELUDE);
  if (iP < 0) fail('PRELUDE not found');
  const head = shared.slice(0, iP);
  const hm = head.match(/^const SPECTRAL_ON: bool = (true|false);\n$/);
  if (!hm) fail('unexpected head ' + JSON.stringify(head));
  let at = iP + K.PRELUDE.length;
  if (shared.slice(at, at + K.SPECTRAL.length) !== K.SPECTRAL) fail('SPECTRAL does not follow PRELUDE');
  at += K.SPECTRAL.length;
  const tab = shared.slice(at, at + 64);
  if (!/^var<private> ETAB: array<f32, 256> = /.test(tab)) fail('the GGX table does not follow SPECTRAL');
  at = shared.indexOf('\n', at) + 1;
  if (shared.slice(at, at + GGX_E.length) !== GGX_E) fail('ggxE does not follow the GGX table');
  at += GGX_E.length;
  const iC = shared.indexOf(K.CORE, at);
  if (iC < 0) fail('CORE not found');
  const fieldCode = shared.slice(at, iC);
  at = iC + K.CORE.length;
  if (shared.slice(at, at + METAL_AT.length) !== METAL_AT) fail('metalAt does not follow CORE');
  at += METAL_AT.length;
  if (!shared.endsWith(K.PATH)) fail('the program does not end with PATH');
  let matCode = shared.slice(at, shared.length - K.PATH.length);
  for (const [name, text] of [['hitAlbedo', HIT_ALBEDO], ['hitEmission', HIT_EMISSION]]) {
    const n = matCode.split(text).length - 1;
    if (n !== 1) fail(name + ' appears ' + n + ' times in the material section');
    matCode = matCode.replace(text, '');
  }
  for (const fn of ['sdUser', 'heightAt', 'densityOf']) if (!new RegExp('\\bfn ' + fn + '\\(').test(fieldCode)) fail(fn + ' missing from the field section');
  for (const fn of ['evalMaterial', 'customKernel']) if (!new RegExp('\\bfn ' + fn + '\\(').test(matCode)) fail(fn + ' missing from the material section');
  return { spectral: hm[1] === 'true', fieldCode, matCode };
}
